赶考的这排碗是 {a}、{b}、{c} 条，限额 {lim} 条 —— **严格超过**限额（等于不算）的碗才叫超限。

referenceSolutionTemplate:
#include <stdio.h>

/* 盘点一排碗里的鱼干：印出合计与超限的碗数。
   超限 = 严格大于 FISH_LIMIT（等于不算）。 */
#define FISH_LIMIT {lim}

/* 这一排一共几只碗。 */
#define BOWL_COUNT 3

/* 把一排碗里的条数加起来。 */
int total_fish(int fish[], int count) {
    int total = 0;
    for (int i = 0; i < count; i++) {
        total += fish[i];
    }
    return total;
}

/* 数一数有几碗严格超过限额。 */
int count_over_limit(int fish[], int count) {
    int over = 0;
    for (int i = 0; i < count; i++) {
        if (fish[i] > FISH_LIMIT) {
            over++;
        }
    }
    return over;
}

int main(void) {
    int fish[BOWL_COUNT] = { {a}, {b}, {c} };
    printf("合计 %d 条喵\n", total_fish(fish, BOWL_COUNT));
    printf("超限 %d 碗喵\n", count_over_limit(fish, BOWL_COUNT));
    return 0;
}
